const sourceKeys=new Map<string,string>();
for(const [key,value] of Object.entries(SR))sourceKeys.set(value,key);
for(const [key,value] of Object.entries(EN))sourceKeys.set(value,key);
export function translate(key:string):string {
  const statusMessage=/^(.*) \((\d{3})\)$/.exec(key);
  if(statusMessage && sourceKeys.get(statusMessage[1])==='error.server')
    return translate('error.server')+' ('+statusMessage[2]+')';
  const resolved=SR[key]!==undefined?key:sourceKeys.get(key);
  if(resolved){const value=selectedLanguage()==='en'?EN[resolved]||SR[resolved]:SR[resolved];return value.replace(/[←]/g,'').replace(/\s{2,}/g,' ').trim();}
  // Unknown keys must never leak into the interface. Plain data remains unchanged.
  return /^[a-zA-Z]+\.[a-zA-Z]/.test(key)?'—':key;
}
export function uiLocale(){return selectedLanguage()==='sr'?'sr-Latn-RS':'en-US';}
export function translationKeys():string[]{return Object.keys(SR);}
export function translationIntegrity(){const sr=new Set(Object.keys(SR)),en=new Set(Object.keys(EN));return {sr:[...sr],en:[...en],missingInEnglish:[...sr].filter(k=>!en.has(k)),missingInSerbian:[...en].filter(k=>!sr.has(k))};}
export function enumLabel(value:string|null|undefined,kind='status'):string {
  if(!value)return '—';
  const code=kind==='role'?value.replace(/^ROLE_/,''):value;
  const key=kind+'.'+code;
  return SR[key]!==undefined?translate(key):value;
}
@Injectable({providedIn:'root'})
export class I18n {
  readonly language=selectedLanguage;
  constructor(){this.language.set(this.restore());}
  private restore():Language {try{return localStorage.getItem(STORAGE_KEY)==='en'?'en':'sr';}catch{return 'sr';}}
  setLanguage(language:Language){this.language.set(language);try{localStorage.setItem(STORAGE_KEY,language);}catch{}}
  toggle(){this.setLanguage(this.language()==='sr'?'en':'sr');}
  t(key:string):string {return translate(key);}
  status(value:string){return enumLabel(value);}
  role(value:string){return enumLabel(value,'role');}
  payment(value:string){return enumLabel(value,'payment');}
  date(value:string|Date,options?:Intl.DateTimeFormatOptions){return new Intl.DateTimeFormat(this.language()==='sr'?'sr-Latn-RS':'en-US',options).format(new Date(value));}
  number(value:number,options?:Intl.NumberFormatOptions){return new Intl.NumberFormat(this.language()==='sr'?'sr-Latn-RS':'en-US',options).format(value);}
}
@Pipe({name:'t',pure:false}) export class TranslatePipe implements PipeTransform {constructor(private i18n:I18n){} transform(key:string){this.i18n.language();return this.i18n.t(key);}}
@Pipe({name:'uiLabel',pure:false}) export class UiLabelPipe implements PipeTransform {
  constructor(private i18n:I18n){}
  transform(value:string|null|undefined,kind='status'){this.i18n.language();return enumLabel(value,kind);}
}

@Pipe({name:'date',pure:false}) export class LocalDatePipe implements PipeTransform {
  constructor(private i18n:I18n){}
  transform(value:string|number|Date|null|undefined,format='mediumDate'):string {
    if(value===null||value===undefined||value==='')return '';
    const options:Intl.DateTimeFormatOptions=format==='HH:mm'?{}:{year:'numeric',month:'2-digit',day:'2-digit'};
    if(format.includes('HH')||format==='short'||format==='medium'){options.hour='2-digit';options.minute='2-digit';}
    if(format.includes('ss'))options.second='2-digit';
    return this.i18n.date(typeof value==='number'?new Date(value):value,options);
  }
}
@Pipe({name:'number',pure:false}) export class LocalNumberPipe implements PipeTransform {
  constructor(private i18n:I18n){}
  transform(value:number|string|null|undefined,digits='1.0-3'):string {
    if(value===null||value===undefined||value==='')return '';
    const match=/^(\d+)\.(\d+)-(\d+)$/.exec(digits);
    return this.i18n.number(Number(value),match?{minimumIntegerDigits:+match[1],minimumFractionDigits:+match[2],maximumFractionDigits:+match[3]}:undefined);
  }
}





/** Presentation only: never writes translated values back to an editor or API. */
export function localizedContent(record:unknown,field:string):string {
  if(!record||typeof record!=='object')return '';
  const row=record as Record<string,unknown>,value=row[field];
  const sr=typeof value==='string'?value:typeof value==='object'&&value?(value as Record<string,string>)['sr']||'':'';
  if(selectedLanguage()==='sr')return sr;
  const english=row[field+'En']??(row['translations'] as Record<string,Record<string,string>>|undefined)?.['en']?.[field]??(typeof value==='object'&&value?(value as Record<string,string>)['en']:undefined);
  return typeof english==='string'&&english.trim()?english:translate(sr);
}
@Pipe({name:'localized',pure:false}) export class LocalizedContentPipe implements PipeTransform {
  constructor(private i18n:I18n){}
  transform(record:unknown,field:string){this.i18n.language();return localizedContent(record,field);}
}
